// Genereras av kallor-kemi/omrade2/exportsite.py (sajtkonv.py, latt_ov.py) – ändra inte för hand.
// Kemi område 2: varje moment i tre nivåer (lättläst, grundtext, fördjupning), skrivet för skärm i sajtens vanliga sidformat. Elevversion, utan facit. Lättläst har interaktiva övningar.
var innehall = window.innehall || {};
innehall["kemi-m-2-1-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Vad är materia?", "text": ["<p><strong>Materia</strong> är allt som har massa och tar plats. Stenar, vatten, träd och du själv är materia. Luft är också materia.</p>", "<p>Materia finns som <strong>fast</strong>, <strong>flytande</strong> och <strong>gas</strong>. Det kallas tillstånd.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_oversikt.png\" alt=\"\"></figure>", "<p>Vatten kan vara is, flytande vatten eller vattenånga. Det är samma ämne.</p>", "<p>Kemister förklarar tillstånden med en modell. Den kallas <strong>partikelmodellen</strong>. Allt består av små partiklar som rör sig.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Materia är allt som har massa och tar plats. Allt består av partiklar.</div>"]}, {"ikon": "✏️", "titel": "Öva: Vad är materia?", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad är materia?", "val": ["Allt som har massa och tar plats", "Bara fasta saker", "Bara saker du kan se"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Luft är materia.", "Vatten kan vara fast, flytande eller gas.", "Is och vatten är olika ämnen."], "ratt": [true, true, false]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["fast", "gas", "partiklar"], "meningar": ["Is är ett § ämne.", "Vattenånga är en §.", "Allt består av små §."], "ratt": ["fast", "gas", "partiklar"]}, {"typ": "skriv", "fraga": "Nämn något som är materia och som du inte kan se.", "borja": "Ett exempel är", "forslag": "Ett exempel är luft. Luft har massa och tar plats."}]}, {"ikon": "📖", "titel": "Ämnen och material", "text": ["<p>Ett <strong>ämne</strong> känns igen på sina <strong>egenskaper</strong>. Fyra viktiga egenskaper är densitet, smältpunkt, kokpunkt och löslighet.</p>", "<p><strong>Densitet</strong> är hur mycket massa ett ämne har per volym.</p>", "<p><strong>densitet = massa / volym</strong></p>", "<p><strong>Exempel:</strong> Ett metallstycke väger 54 g och har volymen 20 cm³. Densiteten är 54 / 20 = 2,7 g/cm³. Det är aluminium.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_vattenforskj.png\" alt=\"\"></figure>", "<p>Ett föremål <strong>flyter</strong> om dess densitet är lägre än vätskans. Det <strong>sjunker</strong> om den är högre.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Densitet (g/cm³)</th></tr><tr><td>Olivolja</td><td>0,91</td></tr><tr><td>Is</td><td>0,92</td></tr><tr><td>Vatten</td><td>1,0</td></tr><tr><td>Aluminium</td><td>2,7</td></tr><tr><td>Järn</td><td>7,8</td></tr></table></div>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_flyta.png\" alt=\"\"></figure>", "<p><strong>Smältpunkten</strong> är temperaturen då ett fast ämne blir flytande. Is smälter vid 0 °C. <strong>Kokpunkten</strong> är temperaturen då en vätska kokar. Vatten kokar vid 100 °C.</p>", "<p><strong>Löslighet</strong> säger hur mycket som går att lösa i vatten. Sand löser sig inte. När inget mer kan lösas är lösningen <strong>mättad</strong>.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Densitet = massa / volym. Lägre densitet än vätskan: flyter. Högre: sjunker.</div>"]}, {"ikon": "✏️", "titel": "Öva: Ämnen och material", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Ett föremål har massan 40 g och volymen 5 cm³. Vilken är densiteten?", "val": ["5 g/cm³", "8 g/cm³", "35 g/cm³"], "ratt": 1}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Is flyter på vatten.", "En järnbult flyter på vatten.", "Vatten kokar vid 100 °C."], "ratt": [true, false, true]}, {"typ": "streck", "fraga": "Dra streck till rätt mening.", "vanster": ["Densitet", "Smältpunkt", "Kokpunkt"], "hoger": ["då en vätska kokar", "då ett fast ämne blir flytande", "massa per volym"], "ratt": ["massa per volym", "då ett fast ämne blir flytande", "då en vätska kokar"]}, {"typ": "skriv", "fraga": "Ett metallstycke väger 27 g och har volymen 10 cm³. Räkna ut densiteten. Flyter det på vatten?", "borja": "Densiteten är", "forslag": "Densiteten är 27 / 10 = 2,7 g/cm³. Det är högre än vattnets 1,0 g/cm³, så det sjunker."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Vad är materia?", "text": ["<p>Allt som har massa och tar plats kallas <strong>materia</strong>. Stenar, vatten, träd, mjölk och du själv är materia, men också sådant du inte ser: luften är materia eftersom den har massa och tar plats. En uppblåst fotboll väger mer än en tom.</p>", "<p>Materia kan finnas i tre vanliga <strong>tillstånd</strong>: fast, flytande och gas. Vatten kan vara is, flytande vatten eller vattenånga, och det är fortfarande samma ämne. Ändå beter sig de tre tillstånden mycket olika.</p>", "<p>För att förklara varför använder kemister en <strong>modell</strong>, partikelmodellen. Den säger att allt består av mycket små partiklar som hela tiden är i rörelse, med tomrum emellan. Hur partiklarna ligger och rör sig bestämmer om ett ämne är fast, flytande eller gas. I det här kapitlet svarar vi på tre frågor:</p>", "<ul><li>Hur beskriver man ämnen och material med hjälp av egenskaper som densitet, smältpunkt, kokpunkt och löslighet?</li><li>Hur förklarar partikelmodellen tillstånd, tillståndsförändringar och blandningar?</li><li>Hur kan man skilja ämnen åt och ta reda på vad ett prov innehåller?</li></ul>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du har en sluten plastpåse fylld med luft. Vad kan du göra för att visa att luften i påsen har massa och tar plats?</div>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_oversikt.png\" alt=\"Bild 2.1 Samma ämne i tre tillstånd: is, flytande vatten och vattenånga. Partikelmodellen visar hur partiklarna ligger.\"><figcaption><strong>Bild 2.1</strong> Samma ämne i tre tillstånd: is, flytande vatten och vattenånga. Partikelmodellen visar hur partiklarna ligger.</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Delområde</th><th>Du lär dig</th></tr><tr><td><strong>2.1</strong> Ämnen, blandningar och partikelmodellen</td><td>Egenskaper som densitet, smältpunkt och kokpunkt, partikelmodellen och skillnaden mellan rena ämnen och blandningar. Labb: densitet och flyta eller sjunka.</td></tr><tr><td><strong>2.2</strong> Separations- och analysmetoder</td><td>Filtrering, avdunstning, destillation, kromatografi och fällning, och hur man identifierar ämnen. Labb: separera sand, salt och vatten.</td></tr></table></div>"], "fragor": [{"f": "Vad menas med materia?", "svar": "Allt som har massa och tar plats, till exempel fasta föremål, vätskor och gaser som luft."}, {"f": "Är luft materia? Hur vet du det?", "svar": "Ja. Luft har massa och tar plats. Det syns till exempel på att en uppblåst fotboll tar plats och väger mer än en tom."}, {"f": "Vad säger partikelmodellen om vad allt är uppbyggt av?", "svar": "Att allt består av små partiklar som hela tiden rör sig, med tomrum emellan."}]}, {"ikon": "📖", "titel": "Ämnen och material", "text": ["<p>Ett <strong>ämne</strong> är en sorts materia med bestämda egenskaper, till exempel vatten, järn eller socker. Ett <strong>material</strong> är det något är gjort av, till exempel trä, glas eller stål. Ett material kan bestå av ett ämne eller av flera ämnen.</p>", "<p>Ämnen känner vi igen på sina <strong>egenskaper</strong>. Några kan du bedöma med sinnena, som färg, form och hårdhet. Men det är bättre att mäta, för sinnena kan lura oss. Fyra mätbara egenskaper är särskilt viktiga: densitet, smältpunkt, kokpunkt och löslighet. Ett ämne har samma värden oavsett hur stort provet är. En liten och en stor bit aluminium har samma densitet.</p>"]}, {"ikon": "📖", "titel": "Densitet", "text": ["<p><strong>Densitet</strong> säger hur mycket massa ett ämne har per volym. Du räknar ut den så här:</p>", "<p><strong>densitet = massa / volym</strong></p>", "<p>Massan mäter du i gram (g) med en våg. Volymen mäter du i kubikcentimeter (cm³) eller milliliter (ml), där 1 ml är lika med 1 cm³. Har ett metallstycke massan 54 g och volymen 20 cm³ är densiteten 54 / 20 = 2,7 g/cm³. Det stämmer med aluminium.</p>", "<p>En fast kropp med oregelbunden form kan du mäta genom <strong>vattenförskjutning</strong>: lägg den i en mätcylinder med vatten och läs av hur mycket vattennivån stiger. Skillnaden är kroppens volym.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_vattenforskj.png\" alt=\"Bild 2.2 Volymen mäts med vattenförskjutning: nivån stiger från 50 ml till 70 ml, så metallstycket har volymen 20 cm³. Värdena är påhittade.\"><figcaption><strong>Bild 2.2</strong> Volymen mäts med vattenförskjutning: nivån stiger från 50 ml till 70 ml, så metallstycket har volymen 20 cm³. Värdena är påhittade.</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Densitet (g/cm³)</th><th>Ämne</th><th>Densitet (g/cm³)</th></tr><tr><td>Luft (normalt tryck)</td><td>0,0013</td><td>Havsvatten (25 °C)</td><td>1,03</td></tr><tr><td>Etanol (20 °C)</td><td>0,79</td><td>Aluminium</td><td>2,7</td></tr><tr><td>Olivolja</td><td>0,91</td><td>Järn</td><td>7,8</td></tr><tr><td>Is</td><td>0,92</td><td>Bly</td><td>11,3</td></tr><tr><td>Vatten (4 °C)</td><td>1,00</td><td>Guld</td><td>19,3</td></tr></table></div>", "<p class=\"not\">Värdena är avrundade från tabeller och kan skilja något mellan källor. Vattnets densitet är som störst vid 4 °C, ca 1,00 g/cm³, och något lägre (0,998 g/cm³) vid 20 °C.</p>"]}, {"ikon": "📖", "titel": "Flyta eller sjunka", "text": ["<p>Du kan använda densitet för att förutsäga om något flyter. Ett föremål flyter i en vätska om dess densitet är <strong>lägre</strong> än vätskans, och sjunker om den är <strong>högre</strong>. Is (0,92 g/cm³) flyter på vatten (ca 1,0 g/cm³), och olivolja flyter på vatten. En järnbult (7,8 g/cm³) sjunker. Havsvatten har något högre densitet än sötvatten, så det är lättare att flyta i havet än i en insjö.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_flyta.png\" alt=\"Bild 2.3 Olja flyter på vatten, en isbit flyter och en järnbult sjunker.\"><figcaption><strong>Bild 2.3</strong> Olja flyter på vatten, en isbit flyter och en järnbult sjunker.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Smältpunkt och kokpunkt", "text": ["<p><strong>Smältpunkten</strong> är den temperatur då ett fast ämne blir flytande. <strong>Kokpunkten</strong> är den temperatur då en vätska kokar och blir gas. Rena ämnen har bestämda värden, så de kan användas för att känna igen ämnet. Vatten smälter vid 0 °C och kokar vid 100 °C vid normalt lufttryck. Etanol, som finns i handsprit, smälter vid −114 °C och kokar vid 78 °C. Det betyder att etanol är gas vid temperaturer där vatten fortfarande är vätska.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Smältpunkt (°C)</th><th>Ämne</th><th>Smältpunkt (°C)</th></tr><tr><td>Is (vatten)</td><td>0</td><td>Aluminium</td><td>658</td></tr><tr><td>Paraffin (ljusvax)</td><td>ca 52</td><td>Bordssalt</td><td>802</td></tr><tr><td>Tenn</td><td>232</td><td>Guld</td><td>1063</td></tr><tr><td>Bly</td><td>327</td><td>Koppar</td><td>1083</td></tr><tr><td>Zink</td><td>419</td><td></td><td></td></tr></table></div>"]}, {"ikon": "📖", "titel": "Löslighet", "text": ["<p><strong>Löslighet</strong> säger hur mycket av ett ämne som går att lösa i en viss mängd lösningsmedel, till exempel vatten. Salt (natriumklorid) löser sig upp till ungefär 36 g i 100 ml vatten vid 20 °C. Socker löser sig mycket bättre, ungefär 190 g per 100 ml vid 25 °C. Sand är <strong>olöslig</strong> i vatten: det löser sig inte alls.</p>", "<p>När lösningsmedlet inte kan ta emot mer av ämnet är lösningen <strong>mättad</strong>. Det som tillsätts därefter blir kvar som fast ämne på botten. Fasta ämnen löser sig oftast bättre i varmt vatten än i kallt, medan gaser löser sig sämre.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>En kub väger 21,6 g och har sidan 2 cm. Räkna ut volymen (sida × sida × sida) och densiteten. Flyter den på vatten?</div>"], "fragor": [{"f": "Vad är skillnaden mellan ett ämne och ett material?", "svar": "Ett ämne är en sorts materia med bestämda egenskaper, t.ex. vatten. Ett material är det något är gjort av och kan vara ett eller flera ämnen, t.ex. trä eller stål."}, {"f": "Hur räknar du ut densitet, och vilka enheter används?", "svar": "Densitet = massa / volym. Enheten är gram per kubikcentimeter (g/cm³), eller g/ml."}, {"f": "Ett metallstycke väger 54 g och har volymen 20 cm³. Vilken densitet har det, och vilket ämne kan det vara?", "svar": "54 g / 20 cm³ = 2,7 g/cm³. Det stämmer med aluminium."}, {"f": "Varför flyter is på vatten?", "svar": "Is har lägre densitet (0,92 g/cm³) än flytande vatten (ca 1,0 g/cm³)."}, {"f": "Vad är skillnaden mellan smältpunkt och kokpunkt?", "svar": "Smältpunkten är temperaturen då ett fast ämne blir flytande. Kokpunkten är temperaturen då en vätska kokar och blir gas."}, {"f": "Vad betyder att en lösning är mättad?", "svar": "Att det inte går att lösa mer av ämnet i lösningsmedlet vid den temperaturen. Överskottet blir kvar som fast ämne."}]}], "begrepp": [{"term": "Densitet", "forklaring": "Massa per volym, t.ex. g/cm³."}, {"term": "Egenskap", "forklaring": "Något som kännetecknar ett ämne."}, {"term": "Materia", "forklaring": "Allt som har massa och tar plats."}, {"term": "Partikel", "forklaring": "En mycket liten byggsten som materia är uppbyggd av."}, {"term": "Tillstånd", "forklaring": "Om ett ämne är fast, flytande eller gas."}, {"term": "Vattenförskjutning", "forklaring": "Sätt att mäta volymen hos ett föremål genom att se hur mycket vattnet stiger."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Vad är materia? Ämnen och material", "text": ["<p>De flesta ämnen blir tätare när de blir fasta: partiklarna kommer närmare varandra, så fast ämne sjunker i sin egen vätska. Vatten gör tvärtom. Is flyter. Det är ovanligt, och det har stor betydelse för liv i sjöar.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/f_vatten4.png\" alt=\"Bild F2.1 Vattnets densitet runt 4 °C (schematisk). Vatten är tätast vid 4 °C. Is har lägre densitet än flytande vatten.\"><figcaption><strong>Bild F2.1</strong> Vattnets densitet runt 4 °C (schematisk). Vatten är tätast vid 4 °C. Is har lägre densitet än flytande vatten.</figcaption></figure>", "<p>Vatten har sin högsta densitet vid <strong>4 °C</strong>, ca 1,00 g/cm³. Kallare vatten blir <em>mindre</em> tätt igen. Vid 20 °C är densiteten ca 0,998 g/cm³, och is har ca 0,92 g/cm³. Orsaken är att vattenmolekylerna i is ordnar sig i ett sexkantigt mönster som tar mer plats än när de ligger oordnat i flytande vatten. Partiklarna ligger alltså glesare i is än i flytande vatten, och isen har lägre densitet.</p>", "<p>Följden: när en sjö kyls på hösten sjunker det kalla ytvattnet tills allt vatten är 4 °C. Kyls ytan ytterligare blir det mindre tätt och ligger kvar överst, och där bildas isen. Isen flyter på ytan och isolerar vattnet under. Djupa sjöar fryser därför sällan till botten, och fisk och andra djur kan överleva i vattnet under isen.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Anta att is hade haft högre densitet än vatten. Vad skulle hända med en sjö under en lång, kall period? Förklara i flera led.</div>"]}, {"ikon": "🧩", "titel": "Vad säger partikelmodellen?", "text": ["<p>Med den enkla modellen ”fast ämne är tätare än vätska” får man fel för vatten. Det visar en gräns för modellen: den tar inte hänsyn till hur krafterna mellan partiklarna ordnar dem. När du ska förklara isens låga densitet behöver modellen kompletteras med att partiklarna i is binds i ett glest, ordnat mönster. Det är ett bra exempel på hur en modell kan vara användbar och ändå behöva byggas ut.</p>"]}], "begrepp": [{"term": "Densitetsmaximum", "forklaring": "Temperaturen där ett ämne är tätast, för vatten 4 °C."}, {"term": "Sexkantigt mönster", "forklaring": "Så ordnar sig vattenmolekylerna i is."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-1-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧩", "titel": "Partikelmodellen", "text": ["<p><strong>Partikelmodellen</strong> säger tre saker:</p>", "<ol><li>Allt består av små partiklar.</li><li>Partiklarna rör sig hela tiden.</li><li>Det finns tomrum mellan partiklarna.</li></ol>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_partikel.png\" alt=\"\"></figure>", "<p>När ett ämne värms rör sig partiklarna snabbare. Då kan ämnet byta tillstånd: <strong>smälta</strong>, <strong>förånga</strong> eller <strong>sublimera</strong>. När det kyls kan det <strong>kondensera</strong> eller <strong>stelna</strong>.</p>", "<p>Medan ett ämne smälter eller kokar ligger temperaturen still.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_tillstand.png\" alt=\"\"></figure>", "<p><strong>Diffusion</strong> är att partiklar sprider sig själva. Därför känner du doften av mat i ett annat rum.</p>", "<p>Modellen är en förenkling. Den visar inte krafterna mellan partiklarna eller hur de egentligen ser ut.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Fast: tätt och vibrerar. Vätska: nära och glider. Gas: långt isär och snabbt.</div>"]}, {"ikon": "✏️", "titel": "Öva: Partikelmodellen", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Hur ligger partiklarna i en gas?", "val": ["Långt ifrån varandra", "Tätt i ett mönster", "Alla står stilla"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt tillståndsförändring.", "vanster": ["Fast till vätska", "Vätska till gas", "Gas till vätska"], "hoger": ["förångning", "kondensation", "smältning"], "ratt": ["smältning", "förångning", "kondensation"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Partiklarna rör sig hela tiden.", "Temperaturen stiger medan is smälter.", "Doft sprids genom diffusion."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["diffusion", "snabbare", "tomrum"], "meningar": ["Det finns § mellan partiklarna.", "Vid högre temperatur rör sig partiklarna §.", "Att partiklar sprider sig kallas §."], "ratt": ["tomrum", "snabbare", "diffusion"]}]}]}, "vanlig": {"sektioner": [{"ikon": "🧩", "titel": "Partikelmodellen", "text": ["<p>Hur kan man förklara att is är hård, vatten rinner och ånga fyller hela rummet? <strong>Partikelmodellen</strong> ger ett svar. Den bygger på tre idéer:</p>", "<ul><li>Allt består av mycket små <strong>partiklar</strong>.</li><li>Partiklarna är hela tiden i <strong>rörelse</strong>. Ju högre temperatur, desto snabbare rör de sig.</li><li>Mellan partiklarna finns <strong>tomrum</strong>, och partiklarna påverkar varandra med krafter.</li></ul>", "<p>Vad en partikel är beror på ämnet. Det kan vara en atom eller en molekyl. Du lär dig mer om atomer i kapitel 3 och om molekyler och joner i kapitel 4. Här ritar vi alla partiklar som runda kulor.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_partikel.png\" alt=\"Bild 2.4 Partikelmodellen för fast ämne, vätska och gas.\"><figcaption><strong>Bild 2.4</strong> Partikelmodellen för fast ämne, vätska och gas.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Fast, flytande och gas", "text": ["<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Fast ämne</th><th>Vätska</th><th>Gas</th></tr><tr><td><strong>Avstånd</strong></td><td>Tätt ihop</td><td>Nära varandra</td><td>Långt ifrån varandra</td></tr><tr><td><strong>Ordning</strong></td><td>Ordnade i ett mönster</td><td>Oordnade</td><td>Oordnade</td></tr><tr><td><strong>Rörelse</strong></td><td>Vibrerar på sin plats</td><td>Glider förbi varandra</td><td>Rör sig snabbt åt alla håll</td></tr><tr><td><strong>Form och volym</strong></td><td>Bestämd form och volym</td><td>Bestämd volym, formen anpassas efter kärlet</td><td>Fyller hela kärlet</td></tr></table></div>", "<p>Därför går ett fast ämne inte att hälla, medan en vätska rinner. En gas kan tryckas ihop, eftersom det finns mycket tomrum mellan partiklarna. En vätska kan knappt tryckas ihop alls.</p>"]}, {"ikon": "📖", "titel": "Tillståndsförändringar", "text": ["<p>När ett ämne värms eller kyls kan det byta tillstånd. Ändringarna har egna namn: <strong>smältning</strong> (fast till vätska), <strong>stelning</strong> (vätska till fast), <strong>förångning</strong> (vätska till gas), <strong>kondensation</strong> (gas till vätska) och <strong>sublimering</strong> (fast direkt till gas). Förångning kan ske på två sätt: <strong>avdunstning</strong> sker bara vid vätskans yta, vid alla temperaturer. <strong>Kokning</strong> sker i hela vätskan vid kokpunkten.</p>", "<p>Med partikelmodellen: när du tillför värme rör sig partiklarna snabbare. När de rör sig tillräckligt snabbt klarar krafterna inte längre att hålla dem på plats i mönstret, och ämnet smälter. Vid ännu högre temperatur flyger partiklarna iväg från varandra, och vätskan blir gas. Att kyla gör tvärtom.</p>", "<p>Det finns något som överraskar. Under tiden ett ämne smälter eller kokar ligger temperaturen <strong>still</strong>, trots att du fortsätter värma. Värmen går åt till att bryta loss partiklarna från varandra och ökar inte rörelsen.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_tillstand.png\" alt=\"Bild 2.5 Tillståndsförändringarna mellan fast, flytande och gas.\"><figcaption><strong>Bild 2.5</strong> Tillståndsförändringarna mellan fast, flytande och gas.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Diffusion och tryck", "text": ["<p>Du kan känna doften av mat från ett annat rum. Doftämnets partiklar rör sig hela tiden, krockar med luftens partiklar och sprids ut. När partiklar sprids själva bland andra partiklar kallas det <strong>diffusion</strong>. Det händer även utan att något rörs om: en droppe färg i stilla vatten färgar efter en stund hela vattnet. Diffusion är snabb i gaser och långsam i vätskor.</p>", "<p>Gaspartiklar rör sig snabbt och slår mot kärlets väggar. Alla slag tillsammans ger ett <strong>tryck</strong>. Om du värmer gasen i en sluten behållare rör sig partiklarna snabbare, slagen blir hårdare och oftare, och trycket ökar. Därför kan en sluten burk spricka om den hettas upp.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_diffusion.png\" alt=\"Bild 2.6 Diffusion: en färgdroppe sprids i vatten, efter hand blir färgen jämn. Partiklarna syns bara i modellen.\"><figcaption><strong>Bild 2.6</strong> Diffusion: en färgdroppe sprids i vatten, efter hand blir färgen jämn. Partiklarna syns bara i modellen.</figcaption></figure>"]}, {"ikon": "🧩", "titel": "Vad modellen inte visar", "text": ["<p>Partikelmodellen är en förenkling. Bilderna är tvådimensionella, men verkligheten är tredimensionell. Bilderna visar inte rörelsen, krafterna mellan partiklarna eller deras energi. Partiklar är inte färgade kulor: färg, lukt och smak hos ämnet förklaras inte av modellen så här enkelt. Och det är inte hela sanningen att partiklarna är runda bollar. När du behöver förklara mer får du använda en bättre modell, till exempel atommodellen i kapitel 3.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är det svårt att rita en bra bild av partiklarnas rörelse på papper? Vilka nya bilder eller hjälpmedel kunde visa det bättre?</div>"], "fragor": [{"f": "Beskriv hur partiklarna rör sig och ligger i ett fast ämne, en vätska och en gas.", "svar": "Fast: tätt, ordnat, vibrerar på plats. Vätska: nära varandra men oordnat, glider förbi varandra. Gas: långt ifrån varandra, rör sig snabbt åt alla håll."}, {"f": "Vad kallas det när en vätska blir gas, och vad kallas det när en gas blir vätska?", "svar": "Förångning (avdunstning eller kokning) och kondensation."}, {"f": "Hur ändras temperaturen medan en isbit smälter?", "svar": "Den ligger still vid 0 °C så länge det finns både is och vatten."}, {"f": "Vad är skillnaden mellan avdunstning och kokning?", "svar": "Avdunstning sker bara vid vätskans yta och vid alla temperaturer. Kokning sker i hela vätskan vid kokpunkten."}, {"f": "Förklara med partiklar varför doften sprids i ett rum.", "svar": "Doftens partiklar rör sig hela tiden och blandar sig med luftens partiklar. Det kallas diffusion."}, {"f": "Nämn två saker som partikelmodellen inte visar.", "svar": "T.ex. kraften mellan partiklarna, hur partiklarna rör sig, hur partiklarna egentligen ser ut och ämnets färg eller lukt."}]}], "begrepp": [{"term": "Diffusion", "forklaring": "Partiklar sprider sig själva ut bland andra partiklar."}, {"term": "Partikelmodellen", "forklaring": "Modell där allt består av små partiklar som rör sig."}, {"term": "Tillstånd", "forklaring": "Fast, flytande eller gas."}]}, "fordjupning": {"sektioner": [{"ikon": "🧩", "titel": "Partikelmodellen", "text": ["<p>I grundtexten lärde du dig att temperaturen ligger still under smältning och kokning. Här tittar vi närmare på vad som sker, och vad kurvan för uppvärmning visar.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/f_uppv.png\" alt=\"Bild F2.2 Uppvärmning av is som tillförs värme jämnt (påhittade värden, schematiskt): temperaturen stiger, ligger still vid smältning, stiger, ligger still vid kokning och stiger sedan igen.\"><figcaption><strong>Bild F2.2</strong> Uppvärmning av is som tillförs värme jämnt (påhittade värden, schematiskt): temperaturen stiger, ligger still vid smältning, stiger, ligger still vid kokning och stiger sedan igen.</figcaption></figure>", "<p>Kurvan visar fem delar. I <strong>A</strong> värms isen och partiklarna vibrerar kraftigare. I <strong>B</strong> smälter isen: temperaturen är 0 °C hela tiden, trots att värme tillförs. I <strong>C</strong> värms vattnet. I <strong>D</strong> kokar vattnet vid 100 °C. I <strong>E</strong> värms vattenångan.</p>", "<p>Förklaring: temperaturen visar hur snabbt partiklarna i genomsnitt rör sig. Under smältningen går värmen åt att bryta loss partiklarna från mönstret, inte att få dem att röra sig snabbare, så temperaturen ändras inte. Det krävs mycket mer energi för att förånga vatten än för att smälta is, eftersom partiklarna då ska skiljas helt från varandra. På kurvan syns det som att platån D är längre än platån B.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du kyler vattenånga. Beskriv hur kylkurvan ser ut och förklara med partikelmodellen vad som händer med energin under kondensationen.</div>"]}, {"ikon": "📖", "titel": "Rent ämne eller blandning?", "text": ["<p>Ett rent ämne smälter och kokar vid en bestämd temperatur, så kurvan har tydliga platåer. En blandning smälter och kokar över ett temperaturområde, så kurvan lutar där i stället. Därför kan en kurva användas för att avgöra om ett prov är rent. Skärpan på platån säger något om renheten, men en mätning bevisar inget: en annan förorening kan ge nästan samma värde.</p>"]}], "begrepp": [{"term": "Platå", "forklaring": "Del av kurvan där temperaturen ligger still."}, {"term": "Tillförd energi", "forklaring": "Värme som ämnet tar upp."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-1-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Rena ämnen och blandningar", "text": ["<p>Ett <strong>rent ämne</strong> har bara en sorts partikel. En <strong>blandning</strong> har minst två ämnen.</p>", "<p>I en <strong>homogen</strong> blandning ser det likadant ut överallt. I en <strong>heterogen</strong> blandning ser du delarna.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_blandning.png\" alt=\"\"></figure>", "<p>Saltvatten är en <strong>lösning</strong>. Vatten är <strong>lösningsmedel</strong> och salt är <strong>löst ämne</strong>.</p>", "<p>En <strong>legering</strong> är en blandning av metaller. Mässing är koppar och zink.</p>", "<p>När du blandar försvinner ingenting. Löser du 5 g salt i 100 g vatten väger lösningen 105 g.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Rent ämne: en sorts partikel. Blandning: minst två. Massan bevaras när man blandar.</div>"]}, {"ikon": "✏️", "titel": "Öva: Rena ämnen och blandningar", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vilken blandning är heterogen?", "val": ["Sand i vatten", "Saltvatten", "Luft"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Saltvatten är en lösning.", "Ett rent ämne har många sorters partiklar.", "En legering är en blandning av metaller."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["105", "blandning", "lösningsmedel"], "meningar": ["I saltvatten är vatten §.", "5 g salt och 100 g vatten ger § g saltvatten.", "Minst två ämnen är en §."], "ratt": ["lösningsmedel", "105", "blandning"]}, {"typ": "skriv", "fraga": "Ge ett exempel på en blandning du har hemma.", "borja": "Ett exempel är", "forslag": "Ett exempel är läsk, som är en blandning av vatten, socker och kolsyra."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Rena ämnen och blandningar", "text": ["<p>Ett <strong>rent ämne</strong> består av bara en sorts partiklar. Destillerat vatten och bordssalt är nästan rena ämnen. En <strong>blandning</strong> innehåller minst två ämnen. De flesta saker du möter är blandningar: luft, mjölk, saltvatten, jord, choklad.</p>", "<p>Ett rent ämne har en bestämd smältpunkt och kokpunkt. För en blandning varierar de med hur mycket av varje ämne som ingår. Därför kan man använda dem för att se om ett prov är rent.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_blandning.png\" alt=\"Bild 2.7 Partikelbilder: ett rent ämne, en homogen blandning (lösning) och en heterogen blandning.\"><figcaption><strong>Bild 2.7</strong> Partikelbilder: ett rent ämne, en homogen blandning (lösning) och en heterogen blandning.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Homogena och heterogena blandningar", "text": ["<p>I en <strong>homogen blandning</strong> är allt blandat så jämnt att det ser likadant ut överallt. Du kan inte se de olika delarna. Saltvatten är ett exempel. I en <strong>heterogen blandning</strong> kan du se eller skilja delarna: sand i vatten, sallad, granit.</p>", "<p>En homogen blandning av ett ämne som löst sig i ett annat kallas <strong>lösning</strong>. Det ämne som löses kallas <strong>löst ämne</strong> och det som löser kallas <strong>lösningsmedel</strong>. I saltvatten är salt det lösta ämnet och vatten lösningsmedlet. Vatten är det vanligaste lösningsmedlet, men det finns fler.</p>", "<p>Luft är en homogen blandning av flera gaser. En blandning av metaller kallas <strong>legering</strong>. Mässing är en legering av koppar och zink, brons av koppar och tenn. Legeringen kan ha helt andra egenskaper än metallerna var för sig, till exempel vara hårdare.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Är en kopp te med socker i homogen eller heterogen? Och en kopp te med tebitar i? Förklara med partikelmodellen.</div>"]}, {"ikon": "📖", "titel": "Vad händer när ämnen blandas?", "text": ["<p>När du blandar ämnen försvinner ingenting. Ämnena finns kvar som de var och går i princip att få tillbaka, så vi kan skilja dem åt (delområde 2.2). Att blanda är inte en kemisk reaktion (se kapitel 4). Därför är <strong>massan</strong> lika stor före och efter: löser du 5 g salt i 100 g vatten får du 105 g saltvatten.</p>"], "fragor": [{"f": "Vad är skillnaden mellan ett rent ämne och en blandning?", "svar": "Ett rent ämne består av bara en sorts partikel. En blandning innehåller minst två ämnen."}, {"f": "Vad är skillnaden mellan en homogen och en heterogen blandning?", "svar": "I en homogen blandning ser det likadant ut överallt, du ser inte delarna. I en heterogen blandning kan du se eller skilja delarna."}, {"f": "Ge ett exempel på en lösning och peka ut lösningsmedel och löst ämne.", "svar": "Saltvatten: vatten är lösningsmedlet och salt är det lösta ämnet."}, {"f": "Vad är en legering?", "svar": "En blandning av metaller, till exempel mässing av koppar och zink."}, {"f": "Du löser 5 g salt i 100 g vatten. Hur mycket väger lösningen?", "svar": "105 g. Massan bevaras när ämnen blandas, ingenting försvinner."}]}], "begrepp": [{"term": "Blandning", "forklaring": "Innehåller minst två ämnen."}, {"term": "Lösning", "forklaring": "Homogen blandning av ett löst ämne i ett lösningsmedel."}, {"term": "Rent ämne", "forklaring": "Består av bara en sorts partikel."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Rena ämnen och blandningar", "text": ["<p>Löslighet kan uttryckas i gram löst ämne per 100 ml lösningsmedel. Det ger dig ett sätt att räkna på lösningar.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/f_losl.png\" alt=\"Bild F2.3 Schematiskt: löslighet hos ett fast ämne ökar oftast med temperaturen, medan en gas blir mindre löslig. Kurvorna är inte uppmätta värden.\"><figcaption><strong>Bild F2.3</strong> Schematiskt: löslighet hos ett fast ämne ökar oftast med temperaturen, medan en gas blir mindre löslig. Kurvorna är inte uppmätta värden.</figcaption></figure>", "<p>Salt (natriumklorid) löser sig upp till ungefär 35,7 g per 100 ml vatten vid 20 °C, och socker ungefär 190 g per 100 ml vid 25 °C. Löser du 20 g salt i 100 ml vatten vid 20 °C löser sig allt, och lösningen är <strong>omättad</strong>. Löser du 50 g går bara 35,7 g att lösa. Resten, 50 − 35,7 = 14,3 g, ligger kvar som fast ämne och lösningen är <strong>mättad</strong>. Värmer du lösningen kan du ofta lösa mer. Löser du i varmt vatten och sedan låter det svalna kan ämnet som inte längre får plats i lösning falla ut som kristaller.</p>", "<p>De flesta fasta ämnen löser sig bättre i varmt vatten, men inte alla lika mycket. För gaser är det tvärtom: de löser sig sämre i varmt vatten. Det är en anledning till att kokt och avkylt vatten smakar ”platt”: gaser som lösts i vattnet har gått bort.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du löser socker i hett te tills det inte går mer, och låter teet svalna. Vad kan hända? Förklara med löslighet.</div>"]}, {"ikon": "📖", "titel": "Mättad lösning och partiklar", "text": ["<p>Med partikelmodellen: i en lösning blandas partiklarna från det lösta ämnet med vattnets partiklar. Det finns en gräns för hur många lösta partiklar vattnet kan ta emot och hålla kvar. När gränsen nås stannar fler partiklar i den fasta fasen. Samtidigt lämnar partiklar fortfarande den fasta ytan och andra återvänder dit, så det är i jämvikt: lika många lämnar som kommer tillbaka. Det är en förklaringsmodell, inte något som syns direkt.</p>"]}], "begrepp": [{"term": "Mättad lösning", "forklaring": "Det går inte att lösa mer vid den temperaturen."}, {"term": "Omättad lösning", "forklaring": "Det går att lösa mer."}, {"term": "Utfällning av kristaller", "forklaring": "Löst ämne som blir fast när det inte längre får plats i lösningen."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-1-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 2.1 Densitet och flyta eller sjunka", "text": ["<p><strong>Fråga:</strong> Kan man förutsäga om ett föremål flyter genom att räkna ut densiteten?</p>", "<p>Du behöver: våg, mätcylinder, vatten, saltlösning, små föremål, skyddsglasögon.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_labb1.png\" alt=\"\"></figure>", "<ol><li>Väg föremålet.</li><li>Mät volymen med vattenförskjutning.</li><li>Räkna ut densiteten.</li><li>Gissa: flyter eller sjunker?</li><li>Prova i vatten.</li><li>Prova ett föremål i saltlösning.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Föremål</th><th>Massa (g)</th><th>Volym (cm³)</th><th>Densitet (g/cm³)</th><th>Flyter eller sjunker?</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Ha skyddsglasögon. Torka upp spill. Använd bara vatten och saltlösning. Smaka inte.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Flyter om densiteten är lägre än 1,0 g/cm³ (vattnets densitet).</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 2.1 Densitet och flyta eller sjunka", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["densitet", "massa", "volym"], "meningar": ["Jag vägde föremålets §.", "Jag mätte § med vattenförskjutning.", "Jag räknade ut §."], "ratt": ["massa", "volym", "densitet"]}, {"typ": "skriv", "fraga": "Stämde din gissning? Skriv vad som hände.", "borja": "Min gissning", "forslag": "Min gissning stämde. Föremålet med lägre densitet än vatten flöt och det med högre sjönk."}, {"typ": "skriv", "fraga": "Varför är det lättare att flyta i saltvatten?", "borja": "Det beror på", "forslag": "Det beror på att saltvatten har högre densitet än vanligt vatten, så fler föremål har lägre densitet än vätskan."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 2.1 Densitet och flyta eller sjunka", "text": ["<p>Du ska mäta massa och volym för olika föremål, räkna ut deras densitet och förutsäga om de flyter eller sjunker. Sedan prövar du din förutsägelse.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_labb1.png\" alt=\"Bild 2.8 Först massan på vågen, sedan volymen med vattenförskjutning, därefter räknar du ut densiteten.\"><figcaption><strong>Bild 2.8</strong> Först massan på vågen, sedan volymen med vattenförskjutning, därefter räknar du ut densiteten.</figcaption></figure>", "<p><strong>Frågeställning:</strong> Kan man förutsäga om ett föremål flyter eller sjunker genom att räkna ut dess densitet?</p>", "<p><strong>Hypotes:</strong> Skriv vilka föremål du tror flyter, och varför.</p>", "<p><strong>Material:</strong> våg, mätcylinder, vatten, saltlösning (20 g salt löst i 100 ml vatten), tre till fem små fasta föremål av olika material som inte löser sig i vatten (till exempel en metallbit, en träbit, en sten, ett stycke plast), skyddsglasögon, trasa.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Väg varje föremål och skriv massan i tabellen.</li><li>Fyll mätcylindern till ungefär hälften med vatten och läs av volymen. Lägg försiktigt ner föremålet så att det blir helt täckt och läs av igen. Skillnaden är föremålets volym.</li><li>Räkna ut densiteten: massa delat med volym. Jämför med vattnets densitet, 1,0 g/cm³, och skriv din förutsägelse: flyter eller sjunker.</li><li>Prova i en bägare med vatten. Stämde din förutsägelse?</li><li>Prova även ett av föremålen i saltlösningen. Sker det något annorlunda? Förklara med densitet.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Föremål som flyter kan du trycka ner under ytan med en tunn pinne för att mäta volymen. Pinnen ska bara vara med i vattnet en liten bit.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Föremål</th><th>Massa (g)</th><th>Volym (cm³)</th><th>Densitet (g/cm³)</th><th>Förutsägelse</th><th>Resultat</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td></tr></table></div>", "<p class=\"not\">Säkerhet: Använd skyddsglasögon. Torka upp spill på golvet direkt så att ingen halkar. Använd bara vatten och saltlösning. Smaka inte på lösningen.</p>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Vilka föremål hade högre densitet än vatten? Sjönk de alla?</li><li>Hur kan ett fartyg av stål flyta fast stål har högre densitet än vatten?</li><li>Varför är det lättare att flyta i saltvatten än i vanligt vatten? Förklara med densitet.</li></ol>"]}], "begrepp": [{"term": "Densitet", "forklaring": "Massa per volym."}, {"term": "Förutsägelse", "forklaring": "En bedömning du gör innan du provar, byggd på din kunskap."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-2-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Filtrering, avdunstning och sedimentering", "text": ["<p>Ämnena i en blandning går att <strong>separera</strong>. Hur du gör beror på vad som skiljer dem.</p>", "<p><strong>Filtrering</strong> skiljer olösligt fast ämne från vätska. Det som blir kvar i filtret är <strong>residuet</strong>. Vätskan som går igenom är <strong>filtratet</strong>.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_filtrering.png\" alt=\"\"></figure>", "<p>Saltet är löst och går igenom filtret. Då kan du <strong>indunsta</strong> vattnet. Vattnet blir ånga och saltet blir kvar.</p>", "<p><strong>Sedimentering</strong> är att tunga partiklar sjunker till botten. Du kan hälla av vätskan.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_flode.png\" alt=\"\"></figure>", "<p>Sand, salt och vatten: först filtrering, sedan indunstning.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Filtrering skiljer fast ämne från vätska. Indunstning ger tillbaka löst ämne.</div>"]}, {"ikon": "✏️", "titel": "Öva: Filtrering, avdunstning och sedimentering", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vad blir kvar i filtret när du filtrerar sand i vatten?", "val": ["Sanden", "Saltet", "Vattnet"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Salt går att filtrera bort från saltvatten.", "Vid indunstning blir saltet kvar.", "Filtratet är vätskan som går igenom."], "ratt": [false, true, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["filtrat", "indunsta", "residu"], "meningar": ["Det som blir kvar i filtret är §.", "Vätskan som går igenom är §.", "För att få tillbaka salt kan du §."], "ratt": ["residu", "filtrat", "indunsta"]}, {"typ": "siffror", "fraga": "Sätt i ordning. Skriv 1, 2 och 3.", "delar": ["Indunsta filtratet", "Blanda sand, salt och vatten", "Filtrera"], "ratt": [3, 1, 2]}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Filtrering, avdunstning och sedimentering", "text": ["<p>Eftersom ämnena i en blandning behåller sina egenskaper kan vi <strong>separera</strong> dem. Hur vi gör beror på vilken egenskap som skiljer dem. Det kan vara att det ena är olösligt, att det ena sjunker, eller att de har olika kokpunkter. I det här momentet möter du tre enkla metoder.</p>"]}, {"ikon": "📖", "titel": "Sedimentering och dekantering", "text": ["<p>Om en fast substans är tyngre än vätskan och inte löser sig sjunker den med tiden till botten. Det kallas <strong>sedimentering</strong> och det som sjunkit kallas sediment. Sedan kan du försiktigt hälla av vätskan. Det kallas <strong>dekantering</strong>. Metoden är enkel men inte särskilt noggrann, för små partiklar kan hänga kvar i vätskan länge.</p>"]}, {"ikon": "📖", "titel": "Filtrering", "text": ["<p>Med <strong>filtrering</strong> separerar du olösliga fasta ämnen från en vätska. Filterpapper har små hål, <strong>porer</strong>. Vätskan och det som är löst går igenom, men fasta partiklar som är större än porerna fastnar. Det som blir kvar i filtret är <strong>residuet</strong>, och vätskan som kommer igenom är <strong>filtratet</strong>.</p>", "<p>Sand i vatten går bra att filtrera. Saltvatten går inte att separera med filtrering: saltet är löst, det vill säga uppdelat i partiklar som är mycket mindre än porerna, så det följer med vattnet genom filtret.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_filtrering.png\" alt=\"Bild 2.9 Filtrering. Sanden fastnar i filtret, saltvattnet rinner igenom.\"><figcaption><strong>Bild 2.9</strong> Filtrering. Sanden fastnar i filtret, saltvattnet rinner igenom.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Avdunstning och indunstning", "text": ["<p>Vill du få tillbaka ett löst ämne kan du få bort lösningsmedlet. Om du låter vattnet <strong>avdunsta</strong> blir det lösta ämnet kvar som fast ämne. Det går snabbare om du värmer, så att vätskan kokar. Då kallas det <strong>indunstning</strong>. Metoden fungerar bra för salt i vatten, eftersom saltet inte följer med ångan. Den fungerar inte om det lösta ämnet själv är lättflyktigt eller bryts ned av värmen.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_flode.png\" alt=\"Bild 2.10 Så separerar du sand, salt och vatten: först filtrering, sedan indunstning.\"><figcaption><strong>Bild 2.10</strong> Så separerar du sand, salt och vatten: först filtrering, sedan indunstning.</figcaption></figure>"], "fragor": [{"f": "Vilken egenskap utnyttjar du när du filtrerar en blandning?", "svar": "Att vissa ämnen är olösliga och partiklarna för stora för att passera filtret, medan det lösta går igenom."}, {"f": "Vad kallas det som är kvar i filtret, och vad kallas det som rinner igenom?", "svar": "Det som är kvar kallas residuet, det som rinner igenom kallas filtratet."}, {"f": "Hur får du tillbaka saltet från saltvatten?", "svar": "Genom att avdunsta eller koka bort vattnet. Saltet blir kvar."}, {"f": "Vad är sedimentering?", "svar": "Att tyngre partiklar sjunker till botten och kan hällas ifrån (dekanteras)."}]}], "begrepp": [{"term": "Filtrat", "forklaring": "Vätskan som rinner igenom filtret."}, {"term": "Residu", "forklaring": "Det fasta som blir kvar i filtret."}, {"term": "Separera", "forklaring": "Skilja ämnen i en blandning från varandra."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Filtrering, avdunstning och sedimentering", "text": ["<p>I labben 2.2 vägde du sand och salt före och efter separationen. Här tittar vi på vad skillnaden i massa säger.</p>", "<p>Kemister räknar <strong>utbyte</strong>: hur stor andel av det som fanns från början som du fick tillbaka.</p>", "<p><strong>utbyte (%) = erhållen massa / ursprunglig massa × 100</strong></p>", "<p><strong>Exempel (påhittat):</strong> Du började med 5,0 g salt och fick 4,6 g salt. Utbytet är 4,6 / 5,0 × 100 = 92 %. De sista 8 procenten kan ha stannat kvar på filtret, bägaren eller skålen, eller sprutat ut vid upphettningen. Ett utbyte över 100 % betyder att något är fel, till exempel att provet är fuktigt eller förorenat.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du får 5,3 g salt av 5,0 g. Är det möjligt att du fick mer än du hade? Vad kan förklara det?</div>"]}, {"ikon": "📖", "titel": "Vad påverkar utbytet och renheten?", "text": ["<p>Utbytet minskar av förluster: material som fastnar på glas och filter, vätska som spills, partiklar som går genom filtret. Renheten påverkas av det som kommer med: sand som är kvar i saltet om filtret läcker, eller fukt om saltet inte torkats. Man kan förbättra båda genom att skölja filtret med lite vatten, torka noga och upprepa mätningen. Ofta väljer man mellan hög renhet och högt utbyte. Det är en avvägning som beror på vad ämnet ska användas till.</p>", "<p>Massan bevaras vid blandning och separation, så summan av det du fick tillbaka och det du förlorade är lika med det du började med. Om siffrorna inte går ihop har något annat än kemin hänt, vilket gör massan till en bra kontroll.</p>"]}], "begrepp": [{"term": "Renhet", "forklaring": "Hur stor del av ett prov som är det önskade ämnet."}, {"term": "Utbyte", "forklaring": "Andelen av ursprunglig mängd som erhålls."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-2-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Destillation och kromatografi", "text": ["<p><strong>Destillation</strong> skiljer ämnen som har olika kokpunkt. Ämnet med lägst kokpunkt blir gas först. Gasen kyls i en kylare och blir vätska igen.</p>", "<p>Med saltvatten blir bara vattnet gas. Saltet blir kvar. Du får rent vatten.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_destillation.png\" alt=\"\"></figure>", "<p>Etanol kokar vid 78 °C och vatten vid 100 °C. I en blandning kokar etanol först.</p>", "<p><strong>Kromatografi</strong> skiljer färger. Vattnet sugs upp i filterpapper och tar med färgerna. Olika färgämnen vandrar olika långt.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_kromatografi.png\" alt=\"\"></figure>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Destillation: olika kokpunkter. Kromatografi: ämnen som vandrar olika långt.</div>"]}, {"ikon": "✏️", "titel": "Öva: Destillation och kromatografi", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Vilket ämne kokar först i en blandning av etanol och vatten?", "val": ["Etanol", "Vatten", "Båda samtidigt"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt metod.", "vanster": ["Rent vatten från saltvatten", "Se vilka färger en tusch innehåller", "Sand från vatten"], "hoger": ["destillation", "filtrering", "kromatografi"], "ratt": ["destillation", "kromatografi", "filtrering"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Kylaren gör ångan till vätska.", "Pennstrecket ska vara under vattenytan.", "Olika färger kan vandra olika långt."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["kokpunkter", "kylare", "papper"], "meningar": ["Destillation utnyttjar olika §.", "Ångan kyls i en §.", "Vid kromatografi sugs vattnet upp i §."], "ratt": ["kokpunkter", "kylare", "papper"]}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Destillation och kromatografi", "text": ["<p>Ibland räcker det inte med filtrering och indunstning. Om du vill ha tillbaka vattnet från saltvatten, eller skilja två vätskor åt, behöver du andra metoder. Destillation utnyttjar att ämnen har <strong>olika kokpunkter</strong>. Kromatografi utnyttjar att ämnen <strong>löser sig olika bra</strong> och fastnar olika mycket.</p>"]}, {"ikon": "📖", "titel": "Destillation", "text": ["<p>Vid <strong>destillation</strong> värms blandningen. Det ämne som har lägst kokpunkt blir gas först. Gasen leds in i en <strong>kylare</strong>, där den kyls och kondenserar till vätska, som samlas upp i ett annat kärl. På så sätt får du det ämnet separat.</p>", "<p>Med saltvatten blir det bara vattnet som blir gas. Saltet har en mycket högre kokpunkt och blir kvar i kolven. Det som samlas upp är därför rent vatten, så metoden går att använda för att göra dricksvatten av havsvatten. Blandar du etanol (kokpunkt 78 °C) och vatten (100 °C) får du mest etanol först. Det är inte en helt skarp separation, för även vatten förångas lite grann, så man kan upprepa processen.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_destillation.png\" alt=\"Bild 2.11 Destillation: ångan kyls i kylaren och droppar ner i uppsamlingskärlet.\"><figcaption><strong>Bild 2.11</strong> Destillation: ångan kyls i kylaren och droppar ner i uppsamlingskärlet.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Kromatografi", "text": ["<p>Många färger är blandningar av flera färgämnen. Med <strong>papperskromatografi</strong> kan du se dem. Du gör en prick eller ett streck med färgen en bit upp på ett filterpapper och ställer papperets nederkant i lite lösningsmedel, till exempel vatten. Vattnet sugs upp i papperet och tar med sig färgämnena. De som löser sig bra i vatten och fastnar lite på papperet vandrar långt. De som fastnar mer vandrar kortare. Färgerna delar sig i band.</p>", "<p>Pennstrecket måste sitta ovanför vattenytan i början. Annars löser färgen ut i vattnet i stället för att vandra upp i papperet. Metoden används av analytiska kemister för att se vilka ämnen ett prov innehåller, till exempel färgämnen i mat eller bläck.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_kromatografi.png\" alt=\"Bild 2.12 Kromatografi: tre färgämnen vandrar olika långt på papperet.\"><figcaption><strong>Bild 2.12</strong> Kromatografi: tre färgämnen vandrar olika långt på papperet.</figcaption></figure>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Vilken metod skulle du välja för att (a) få ut socker ur sockervatten, (b) få rent vatten ur sockervatten, (c) se vilka färger som ingår i grön tuschpenna? Motivera.</div>"], "fragor": [{"f": "Vilken skillnad mellan ämnen utnyttjas vid destillation?", "svar": "Olika kokpunkter."}, {"f": "Vilket ämne kokar först när du destillerar en blandning av etanol (78 °C) och vatten (100 °C)?", "svar": "Etanol, eftersom den har lägst kokpunkt."}, {"f": "Vad är kylarens uppgift vid destillation?", "svar": "Att kyla ångan så att den kondenserar till vätska som kan samlas upp."}, {"f": "Varför vandrar olika färger olika långt på filterpapperet vid kromatografi?", "svar": "Ämnena löser sig olika bra i lösningsmedlet och fastnar olika mycket på papperet."}, {"f": "Varför ska pennstrecket sitta ovanför vattenytan i början?", "svar": "Annars löser färgen ut i vattnet i stället för att vandra upp i papperet."}]}], "begrepp": [{"term": "Destillation", "forklaring": "Separation som utnyttjar olika kokpunkter."}, {"term": "Kondensera", "forklaring": "Gå från gas till vätska."}, {"term": "Kromatografi", "forklaring": "Separation som utnyttjar att ämnen vandrar olika långt."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Destillation och kromatografi", "text": ["<p>Destillation fungerar bäst när ämnena har mycket olika kokpunkter, som vatten och salt. Vad händer när kokpunkterna ligger nära varandra, och hur kan man mäta hur långt ett ämne vandrar vid kromatografi?</p>", "<p>Etanol kokar vid 78 °C och vatten vid 100 °C. Ångan från en kokande blandning innehåller mest etanol, men också lite vatten. En enkel destillation ger därför ett destillat som är rikare på etanol men inte rent. Vid <strong>fraktionerad destillation</strong> leds ångan genom en kolonn där den kondenserar och förångas om och om igen. Varje gång blir ångan lite rikare på det ämne som har lägst kokpunkt, och längst upp kommer nästan ren etanol ut. Samma princip används för att dela upp blandningar av många vätskor med olika kokpunkter.</p>", "<p>Termometern visar vad som händer: så länge etanol destillerar ligger temperaturen nära 78 °C. När etanolen tar slut stiger den mot 100 °C. Det går att byta uppsamlingskärl vid temperaturhoppet och få olika fraktioner.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför är det svårare att separera två vätskor med kokpunkterna 78 °C och 82 °C än med 78 °C och 100 °C? Förklara med ångans sammansättning.</div>"]}, {"ikon": "📖", "titel": "Rf-värde i kromatografi", "text": ["<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/f_rf.png\" alt=\"Bild F2.4 Ett kromatogram. Rf-värdet för varje färg är sträckan färgen vandrat delat med sträckan lösningsmedlet vandrat (påhittade mått).\"><figcaption><strong>Bild F2.4</strong> Ett kromatogram. Rf-värdet för varje färg är sträckan färgen vandrat delat med sträckan lösningsmedlet vandrat (påhittade mått).</figcaption></figure>", "<p>Vid papperskromatografi kan du mäta hur långt varje ämne vandrat. <strong>Rf-värdet</strong> är sträckan ämnet vandrat delat med sträckan lösningsmedlet vandrat, mätt från startlinjen: Rf = a / b. Ett Rf-värde ligger mellan 0 och 1. Om lösningsmedlet vandrat 8,0 cm och en färg 3,2 cm blir Rf = 3,2 / 8,0 = 0,40. Under lika förhållanden har ett ämne alltid samma Rf-värde, så man kan jämföra med kända ämnen och identifiera dem. Det kräver samma papper, samma lösningsmedel och att mätningen görs vid samma förhållanden.</p>"]}], "begrepp": [{"term": "Fraktion", "forklaring": "En del av blandningen som samlats vid ett visst temperaturintervall."}, {"term": "Fraktionerad destillation", "forklaring": "Destillation där ångan upprepat kondenseras i en kolonn för bättre separation."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-2-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "Identifiera ämnen och fällning", "text": ["<p>Man kan <strong>identifiera</strong> ett ämne genom att mäta egenskaper och jämföra med en tabell.</p>", "<p>Ett metallstycke med densiteten 2,7 g/cm³ är troligen aluminium.</p>", "<p>En egenskap räcker sällan. Mät flera.</p>", "<p>En <strong>fällning</strong> är ett fast ämne som bildas när du blandar två klara lösningar. Blandningen blir grumlig.</p>", "<p>Fällning används i reningsverk. Man får fosfat i avloppsvatten att bilda ett fast ämne. Det kan sedan filtreras bort.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_felling.png\" alt=\"\"></figure>", "<p>En analys kan visa <em>vad</em> som finns, men inte alltid <em>hur mycket</em>. Provet kan också vara förorenat.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Mät flera egenskaper. En fällning är ett fast ämne som bildas när lösningar blandas.</div>"]}, {"ikon": "✏️", "titel": "Öva: Identifiera ämnen och fällning", "text": [], "ovningar": [{"typ": "ringa", "fraga": "Varför mäter man flera egenskaper?", "val": ["Flera ämnen kan ha samma värde på en egenskap", "Det är roligare", "En egenskap är alltid fel"], "ratt": 0}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["En fällning är ett fast ämne som bildas.", "En analys säger alltid hur mycket det finns.", "Fällning används för att rena vatten."], "ratt": [true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["egenskaper", "fällning", "identifiera"], "meningar": ["Att ta reda på vad ett ämne är kallas att §.", "Man jämför § med en tabell.", "Ett fast ämne som bildas vid blandning är en §."], "ratt": ["identifiera", "egenskaper", "fällning"]}, {"typ": "skriv", "fraga": "Du får ett vitt pulver. Hur kan du ta reda på om det är salt eller socker utan att smaka?", "borja": "Jag kan", "forslag": "Jag kan mäta smältpunkt och densitet och se hur lätt det löser sig i vatten, och jämföra med tabellvärden för salt och socker."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Identifiera ämnen och fällning", "text": ["<p>Hur tar man reda på vad ett okänt ämne är? Kemister <strong>identifierar</strong> ämnen genom att mäta egenskaper och jämföra med kända värden i tabeller. Ett fast ämne som är vitt, löser sig i vatten och smälter vid 802 °C är sannolikt bordssalt. Ett metallstycke med densiteten 2,7 g/cm³ är sannolikt aluminium.</p>", "<p>En enda egenskap räcker sällan. Flera ämnen kan ha nästan samma värde på en egenskap, så man mäter flera och ser om alla stämmer. Ju fler som stämmer, desto säkrare är slutsatsen.</p>"]}, {"ikon": "🧪", "titel": "Kemiska tester och indikatorer", "text": ["<p>Ibland används kemiska tester. En <strong>indikator</strong> är ett ämne som byter färg beroende på om en lösning är sur eller basisk. Det används för att pröva lösningar. Hur syror, baser och pH fungerar får du lära dig i kapitel 5. Här räcker det att veta att färgen på en indikator kan bli en ledtråd.</p>"]}, {"ikon": "📖", "titel": "Fällning", "text": ["<p>Ibland blir en klar lösning grumlig när du blandar den med en annan klar lösning. Då har ett nytt, olösligt ämne bildats. Det fasta ämnet kallas en <strong>fällning</strong> och sjunker oftast med tiden. Fällning är en kemisk reaktion, och den kan användas för att visa att ett visst löst ämne finns i provet.</p>", "<p>Fällning används också för att rena vatten. I ett reningsverk kan man tillsätta ett ämne som får lösta ämnen, till exempel fosfat, att bilda ett fast ämne. Det kan sedan filtreras eller sedimenteras bort. Fosfat vill man få bort från avloppsvatten eftersom för mycket fosfat i sjöar och hav ger algblomning. Vid avhärdning av hårt vatten kan man tillsätta kalk och soda, så att kalcium och magnesium fälls ut som fasta ämnen.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_felling.png\" alt=\"Bild 2.13 Fällning: två klara lösningar blandas och ett fast ämne bildas.\"><figcaption><strong>Bild 2.13</strong> Fällning: två klara lösningar blandas och ett fast ämne bildas.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Vad kan en analys säga?", "text": ["<p>En analys kan svara på vilka ämnen som finns i ett prov, men det är inte alltid den svarar på <em>hur mycket</em>. Ett test kan också ge fel svar om provet är förorenat, om metoden inte är känslig nog, eller om flera ämnen ger samma reaktion. Dessutom säger ett prov bara något om just det provet. Ett vattenprov från en plats behöver inte stämma för hela sjön. Därför gör man upprepade prov och olika metoder, och redovisar hur säker slutsatsen är.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Du får ett vitt pulver och ska ta reda på om det är socker eller salt. Vilka egenskaper kan du mäta eller testa utan att smaka på det? Vad behöver du för att kunna jämföra?</div>"], "fragor": [{"f": "Hur kan du identifiera ett okänt fast ämne?", "svar": "Mät flera egenskaper, t.ex. densitet, smältpunkt och löslighet, och jämför med en tabell."}, {"f": "Varför räcker det ofta inte med en enda egenskap för att identifiera ett ämne?", "svar": "Flera ämnen kan ha ungefär samma värde på en egenskap. Flera egenskaper tillsammans ger en säkrare slutsats."}, {"f": "Vad är en fällning?", "svar": "Ett fast ämne som bildas när två lösningar blandas och som sjunker eller svävar i vätskan."}, {"f": "Hur används fällning vid rening av avloppsvatten?", "svar": "Man tillsätter ett ämne så att t.ex. fosfat bildar ett fast ämne som sedan kan filtreras bort."}, {"f": "Nämn en sak som en analys inte kan säga.", "svar": "T.ex. hur mycket det finns av ett ämne (om testet bara visar om det finns), eller om provet är representativt för allt."}]}], "begrepp": [{"term": "Fällning", "forklaring": "Fast ämne som bildas när två lösningar blandas."}, {"term": "Identifiera", "forklaring": "Ta reda på vad ett ämne är."}, {"term": "Indikator", "forklaring": "Ämne som byter färg vid ändrade förhållanden."}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Identifiera ämnen och fällning", "text": ["<p>Du har ett okänt prov och ska ta reda på vad det innehåller. Hur planerar du, och hur säker blir slutsatsen?</p>", "<p>En bra plan har tydlig fråga, flera <em>oberoende</em> metoder, jämförelser med kända ämnen och upprepade mätningar. Exempel: ett vitt pulver. Du mäter löslighet i vatten, smältpunkt, om det bildar fällning med en känd lösning och jämför med salt och socker som du vet vad de är. Om alla resultat stämmer med ett ämne är slutsatsen stark. Om bara ett stämmer är den svag.</p>", "<p>Ett prov kan vara en blandning, och en metod kan störas av andra ämnen. En <strong>kontrollprov</strong> med ett känt ämne visar om metoden fungerar och om utrustningen är rätt. Ett <strong>blankprov</strong> utan det du letar efter visar om något annat ger utslag.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Ett test visar ”ingen fällning” i ett vattenprov. Betyder det att ämnet inte finns i provet? Ge två skäl till att svaret kan vara ett nej fastän ämnet finns.</div>"]}, {"ikon": "📖", "titel": "Gränser", "text": ["<p>En analys säger bara något om det prov du tagit. Ett vattenprov från en plats och en dag säger inte hur det är i hela sjön hela året. Dessutom har varje metod en gräns för hur lite av ett ämne den klarar att upptäcka. Hittar du inget kan det finnas så lite att metoden inte ser det. Därför ska en slutsats formuleras med försiktighet: ”Vi fann inget fosfat med den här metoden” är något annat än ”det finns inget fosfat”. Redovisa också hur provet togs, hur många prov som togs och vilka felkällor som finns.</p>"]}], "begrepp": [{"term": "Blankprov", "forklaring": "Prov utan det du letar efter, för att se om något annat ger utslag."}, {"term": "Kontrollprov", "forklaring": "Prov med känt innehåll som visar att metoden fungerar."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-2-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 2.2 Separera sand, salt och vatten", "text": ["<p><strong>Fråga:</strong> Hur separerar man sand, salt och vatten, och hur mycket får man tillbaka?</p>", "<p>Du behöver: blandning (10 g sand, 5 g salt, 100 ml vatten), våg, tratt, filterpapper, bägare, skål, värmeplatta, tång, skyddsglasögon.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_labb2.png\" alt=\"\"></figure>", "<ol><li>Filtrera blandningen.</li><li>Låt sanden torka. Väg den.</li><li>Indunsta filtratet i en skål. Stäng av innan allt vatten är borta.</li><li>Låt skålen svalna. Väg saltet.</li><li>Gör kromatografi med färgpennor som extra uppgift.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Massa före (g)</th><th>Massa efter (g)</th></tr><tr><td>Sand</td><td>10</td><td></td></tr><tr><td>Salt</td><td>5</td><td></td></tr></table></div>", "<p><strong>Säkerhet:</strong> Ha skyddsglasögon. Skålen blir mycket varm: använd tång. Smaka inget. Samla håret.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Först filtrering för sanden. Sedan indunstning för saltet.</div>"]}, {"ikon": "✏️", "titel": "Öva: Labb 2.2 Separera sand, salt och vatten", "text": [], "ovningar": [{"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["filtrat", "saltet", "sanden"], "meningar": ["Filtret fångade §.", "Vid indunstningen blev § kvar.", "Vätskan som gick igenom är §."], "ratt": ["sanden", "saltet", "filtrat"]}, {"typ": "skriv", "fraga": "Hur mycket sand och salt fick du tillbaka? Skriv dina värden.", "borja": "Jag fick", "forslag": "Jag fick tillbaka ungefär lika mycket sand och salt som jag började med, men något mindre. Värdena skiljer mellan grupper."}, {"typ": "skriv", "fraga": "Varför fick du inte tillbaka exakt allt?", "borja": "Det beror på", "forslag": "Det beror på att något material fastnade på filtret och bägaren, eller sprutade vid upphettning."}]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb 2.2 Separera sand, salt och vatten", "text": ["<p>Du får en blandning av sand, salt och vatten. Din uppgift är att planera hur du separerar dem och sedan ta reda på hur mycket du fick tillbaka. Därefter prövar du kromatografi på färgade pennor.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/kemi-omrade2/v_labb2.png\" alt=\"Bild 2.14 Filtrera blandningen, och indunsta filtratet i en skål. Kromatografin görs separat med filterpapper.\"><figcaption><strong>Bild 2.14</strong> Filtrera blandningen, och indunsta filtratet i en skål. Kromatografin görs separat med filterpapper.</figcaption></figure>", "<p><strong>Frågeställning:</strong> Hur kan man separera sand, salt och vatten ur en blandning, och hur mycket får man tillbaka?</p>", "<p><strong>Hypotes:</strong> Hur tror du att du får tillbaka allt? Vilken ordning ska metoderna komma i?</p>", "<p><strong>Material:</strong> blandning av 10 g sand och 5 g salt i 100 ml vatten, våg, tratt, filterpapper, bägare, porslinsskål eller metallskål, värmeplatta, tång eller grytlappar, glasstav och 2–3 olika vattenlösliga färgpennor till kromatografin, lite vatten, skyddsglasögon.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Väg ett tomt filterpapper och vik det i tratten över en ren bägare.</li><li>Häll blandningen långsamt genom filtret. Skölj ur bägaren med lite vatten.</li><li>Låt sanden torka, väg den och dra av filterpapperets massa.</li><li>Väg den tomma skålen. Indunsta filtratet i skålen på värmeplattan. Stäng av värmen när lite vätska återstår så att saltet inte spritter.</li><li>Låt skålen svalna. Väg den och räkna ut saltets massa.</li><li>Kromatografi: rita ett streck med en penna en bit upp på ett filterpapper, ställ nederkanten i lite vatten (strecket ovanför ytan) och jämför banden när vattnet nått nästan till toppen.</li></ol>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Bra att veta</span>Smaka aldrig på något i labbet, inte heller på saltet. Skålen blir mycket varm, så använd tång.</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ämne</th><th>Massa före (g)</th><th>Massa efter (g)</th><th>Skillnad (g)</th></tr><tr><td>Sand</td><td></td><td></td><td></td></tr><tr><td>Salt</td><td></td><td></td><td></td></tr></table></div>", "<p class=\"not\">Säkerhet: Använd skyddsglasögon. Skålen och värmeplattan blir mycket varma: använd tång och rör inte. Smaka inget. Håll håret samlat. Torka upp spill.</p>"]}, {"ikon": "❓", "titel": "Frågor", "text": ["<ol><li>Varför fungerade filtreringen på sanden men inte på saltet?</li><li>Hur mycket av sanden och saltet fick du tillbaka? Vilka felkällor kan förklara skillnaden?</li><li>Vilka band fick du i kromatografin? Vad säger det om pennornas färger?</li></ol>"]}], "begrepp": [{"term": "Filtrat", "forklaring": "Vätskan som kommer genom filtret."}, {"term": "Residu", "forklaring": "Det som blir kvar i filtret."}, {"term": "Utbyte", "forklaring": "Hur mycket du fick tillbaka jämfört med hur mycket du hade."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-s"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p>", "<p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p>", "<ul class=\"viktigast\"><li>Materia är allt som har massa och tar plats. Den finns som fast, flytande och gas.</li></ul>", "<ul class=\"viktigast\"><li>Densitet = massa / volym. Lägre densitet än vätskan: flyter.</li></ul>", "<ul class=\"viktigast\"><li>Partikelmodellen: allt består av partiklar som rör sig, med tomrum emellan.</li></ul>", "<ul class=\"viktigast\"><li>Rent ämne har en sorts partikel. Blandning har minst två. Massan bevaras.</li></ul>", "<ul class=\"viktigast\"><li>Filtrering skiljer fast ämne från vätska. Indunstning ger tillbaka löst ämne.</li></ul>", "<ul class=\"viktigast\"><li>Destillation utnyttjar olika kokpunkter. Kromatografi skiljer färger.</li></ul>", "<ul class=\"viktigast\"><li>Identifiera ett ämne genom att mäta flera egenskaper och jämföra med en tabell.</li></ul>", "<ul class=\"viktigast\"><li>En fällning är ett fast ämne som bildas när lösningar blandas.</li></ul>"]}], "begrepp": [{"term": "blandning", "forklaring": "minst två ämnen tillsammans"}, {"term": "densitet", "forklaring": "hur mycket massa ett ämne har per volym"}, {"term": "destillation", "forklaring": "man skiljer ämnen som kokar vid olika temperatur"}, {"term": "diffusion", "forklaring": "partiklar som sprider sig själva"}, {"term": "egenskap", "forklaring": "något som kännetecknar ett ämne"}, {"term": "filtrering", "forklaring": "man skiljer fast ämne från vätska"}, {"term": "fällning", "forklaring": "ett fast ämne som bildas när lösningar blandas"}, {"term": "kokpunkt", "forklaring": "temperaturen då en vätska kokar"}, {"term": "kromatografi", "forklaring": "man skiljer färger som vandrar olika långt"}, {"term": "löslighet", "forklaring": "hur mycket som går att lösa i vatten"}, {"term": "lösning", "forklaring": "ett ämne som är löst i ett annat"}, {"term": "materia", "forklaring": "allt som har massa och tar plats"}, {"term": "partikel", "forklaring": "en mycket liten bit som allt är uppbyggt av"}, {"term": "rent ämne", "forklaring": "bara en sorts partikel"}, {"term": "smältpunkt", "forklaring": "temperaturen då ett fast ämne blir flytande"}, {"term": "tillstånd", "forklaring": "fast, flytande eller gas"}, {"term": "tryck", "forklaring": "gaspartiklarnas slag mot väggarna"}, {"term": "ämne", "forklaring": "en sorts material, till exempel vatten eller järn"}]}, "vanlig": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<ul><li><strong>Materia</strong> är allt som har massa och tar plats. Materia finns som fast, flytande eller gas (tillstånd).</li><li>Ett <strong>ämne</strong> känns igen på sina egenskaper: <strong>densitet</strong>, <strong>smältpunkt</strong>, <strong>kokpunkt</strong> och <strong>löslighet</strong>.</li><li><strong>Densitet</strong> = massa / volym. Ett föremål flyter i en vätska om dess densitet är lägre än vätskans.</li><li><strong>Partikelmodellen</strong>: allt består av partiklar som rör sig, med tomrum emellan. I fasta ämnen ligger de tätt och ordnat, i vätskor nära men oordnat, i gaser långt isär.</li><li>Tillståndsförändringar är <strong>smältning, stelning, förångning, kondensation</strong> och <strong>sublimering</strong>. Temperaturen ligger still medan ett ämne smälter eller kokar.</li><li><strong>Diffusion</strong> är att partiklar sprider sig bland varandra. Gaser får <strong>tryck</strong> av att partiklarna slår mot väggarna.</li><li>Modellen visar inte krafter, rörelse eller att partiklar är något annat än bollar. Den är en förenkling.</li><li>Ett <strong>rent ämne</strong> har en sorts partiklar. En <strong>blandning</strong> har minst två. Blandningar är <strong>homogena</strong> eller <strong>heterogena</strong>. En <strong>lösning</strong> har ett löst ämne i ett lösningsmedel. En <strong>legering</strong> är en blandning av metaller.</li><li>Vid blandning bevaras massan. Ämnena finns kvar och kan separeras.</li><li><strong>Filtrering</strong> skiljer fast från vätska, <strong>indunstning</strong> får tillbaka löst ämne, <strong>destillation</strong> utnyttjar olika kokpunkter och <strong>kromatografi</strong> skiljer ämnen som vandrar olika långt.</li><li>Ämnen <strong>identifieras</strong> genom att mäta flera egenskaper. En <strong>fällning</strong> är ett fast ämne som bildas när lösningar blandas. En analys har gränser.</li></ul>"]}], "begrepp": [{"term": "Avdunstning", "forklaring": "Förångning som sker vid vätskans yta."}, {"term": "Blandning", "forklaring": "Innehåller minst två ämnen."}, {"term": "Densitet", "forklaring": "Massa per volym."}, {"term": "Destillation", "forklaring": "Separation som utnyttjar olika kokpunkter."}, {"term": "Diffusion", "forklaring": "Partiklar som sprider sig bland andra partiklar."}, {"term": "Filtrering", "forklaring": "Separation av olösligt fast ämne och vätska."}, {"term": "Fällning", "forklaring": "Fast ämne som bildas när lösningar blandas."}, {"term": "Gas", "forklaring": "Tillstånd där partiklarna är långt ifrån varandra."}, {"term": "Heterogen blandning", "forklaring": "Blandning där delarna syns eller kan skiljas åt."}, {"term": "Homogen blandning", "forklaring": "Blandning som ser likadan ut överallt."}, {"term": "Kokpunkt", "forklaring": "Temperaturen då en vätska kokar."}, {"term": "Kondensation", "forklaring": "Gas blir vätska."}, {"term": "Kromatografi", "forklaring": "Separation av ämnen som vandrar olika långt."}, {"term": "Legering", "forklaring": "Blandning av metaller."}, {"term": "Löslighet", "forklaring": "Hur mycket som går att lösa i ett lösningsmedel."}, {"term": "Lösning", "forklaring": "Homogen blandning av löst ämne och lösningsmedel."}, {"term": "Materia", "forklaring": "Allt som har massa och tar plats."}, {"term": "Mättad lösning", "forklaring": "Lösning som inte kan lösa mer."}, {"term": "Partikelmodellen", "forklaring": "Modell där allt består av små partiklar i rörelse."}, {"term": "Rent ämne", "forklaring": "Består av en sorts partikel."}, {"term": "Smältpunkt", "forklaring": "Temperaturen då ett fast ämne smälter."}, {"term": "Sublimering", "forklaring": "Fast ämne blir gas direkt."}, {"term": "Tillstånd", "forklaring": "Fast, flytande eller gas."}, {"term": "Tryck", "forklaring": "Gaspartiklarnas slag mot väggarna."}, {"term": "Vattenförskjutning", "forklaring": "Metod att mäta volym."}]}}, nivaStandard: "vanlig"};
innehall["kemi-m-2-t"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📝", "titel": "Testa dig själv", "text": ["Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill."], "ovningar": [{"typ": "ringa", "fraga": "Hur ligger partiklarna i ett fast ämne?", "val": ["Tätt i ett mönster", "Långt ifrån varandra", "De rör sig fritt"], "ratt": 0}, {"typ": "streck", "fraga": "Dra streck till rätt förklaring.", "vanster": ["Densitet", "Filtrering", "Blandning", "Fällning"], "hoger": ["ett fast ämne bildas", "massa per volym", "minst två ämnen", "skiljer fast från vätska"], "ratt": ["massa per volym", "skiljer fast från vätska", "minst två ämnen", "ett fast ämne bildas"]}, {"typ": "sf", "fraga": "Kryssa i rätt ruta.", "pastaenden": ["Is flyter på vatten.", "Temperaturen stiger medan is smälter.", "Saltvatten är en homogen blandning.", "Destillation utnyttjar olika kokpunkter.", "Luft är inte materia.", "Mässing är en legering."], "ratt": [true, false, true, true, false, true]}, {"typ": "fyll", "fraga": "Välj rätt ord.", "ord": ["indunsta", "kondensation", "partiklar"], "meningar": ["Allt består av §.", "Gas som blir vätska kallas §.", "För att få tillbaka salt kan du § vattnet."], "ratt": ["partiklar", "kondensation", "indunsta"]}, {"typ": "siffror", "fraga": "Sätt i ordning. Skriv 1, 2, 3 och 4.", "delar": ["Indunsta filtratet", "Filtrera", "Blanda sand, salt och vatten", "Väg saltet"], "ratt": [3, 2, 1, 4]}, {"typ": "skriv", "fraga": "Räkna ut densiteten för ett föremål med massan 30 g och volymen 10 cm³.", "borja": "Densiteten är", "forslag": "Densiteten är 30 / 10 = 3 g/cm³."}, {"typ": "skriv", "fraga": "Varför flyter is på vatten?", "borja": "Det beror på att", "forslag": "Det beror på att is har lägre densitet än flytande vatten."}, {"typ": "skriv", "fraga": "Hur kan du få rent vatten från saltvatten?", "borja": "Man kan", "forslag": "Man kan destillera saltvattnet: vattnet kokar och ångan kyls till rent vatten, saltet blir kvar."}]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Del A · Välj ett alternativ", "text": ["Uppgifterna liknar uppgifterna på nationella prov i kemi. Personer, annonser och mätvärden är påhittade."], "ovningar": [{"typ": "ringa", "fraga": "Ett föremål har massan 40 g och volymen 5 cm³. Vilken densitet har det?", "val": ["0,125 g/cm³", "8 g/cm³", "35 g/cm³", "200 g/cm³"], "ratt": 1}, {"typ": "ringa", "fraga": "Vilket påstående om partiklarna i en gas stämmer?", "val": ["De ligger tätt i ett mönster.", "De glider förbi varandra men ligger nära varandra.", "De är långt ifrån varandra och rör sig snabbt åt alla håll.", "De står stilla."], "ratt": 2}, {"typ": "ringa", "fraga": "Vilken metod använder du för att separera sand från vatten?", "val": ["Destillation", "Filtrering", "Kromatografi", "Fällning"], "ratt": 1}, {"typ": "ringa", "fraga": "Vad är en legering?", "val": ["En lösning av salt i vatten.", "En blandning av metaller.", "Ett rent ämne.", "En gas."], "ratt": 1}]}, {"ikon": "📖", "titel": "Del B · Svara kort", "text": [], "ovningar": [{"typ": "fri", "fraga": "Förklara varför is flyter på vatten. Använd begreppet densitet.", "forslag": "Is har lägre densitet (ca 0,92 g/cm³) än flytande vatten (ca 1,0 g/cm³). Ett föremål med lägre densitet än vätskan flyter. Isen tar mer plats än samma massa vatten."}, {"typ": "fri", "fraga": "Förklara vad som menas med en mättad lösning.", "forslag": "En lösning som inte kan lösa mer av ämnet vid den temperaturen. Det som tillsätts efter det blir kvar som fast ämne på botten."}]}, {"ikon": "📖", "titel": "Del C · Tolka resultat och förklara", "text": [], "ovningar": [{"typ": "fri", "fraga": "Elin mätte massan och volymen hos tre små föremål av olika material. Mätvärdena är påhittade. Vattnets densitet är 1,0 g/cm³.<br><div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Föremål</th><th>Massa (g)</th><th>Volym (cm³)</th></tr><tr><td>A</td><td>27</td><td>10</td></tr><tr><td>B</td><td>78</td><td>10</td></tr><tr><td>C</td><td>9,2</td><td>10</td></tr></table></div>a) Räkna ut densiteten för varje föremål.<br>b) Vilka föremål flyter på vatten och vilka sjunker? Förklara.<br>c) Vilket av föremålen kan vara järn (7,8 g/cm³) och vilket kan vara aluminium (2,7 g/cm³)?", "forslag": "a) A: 27/10 = 2,7 g/cm³. B: 78/10 = 7,8 g/cm³. C: 9,2/10 = 0,92 g/cm³. b) C flyter (lägre densitet än 1,0), A och B sjunker (högre densitet). c) A kan vara aluminium (2,7), B kan vara järn (7,8)."}, {"typ": "fri", "fraga": "Förklara med partikelmodellen vad som händer med partiklarna när vatten kokar, och varför temperaturen ligger still under tiden.", "forslag": "Partiklarna får värme och rör sig så snabbt att de lämnar vätskan och blir gas, överallt i vätskan. Under kokningen går värmen åt att bryta loss partiklarna från varandra, inte till att öka rörelsen, så temperaturen ligger still vid kokpunkten."}]}, {"ikon": "📖", "titel": "Del D · Resonera och ta ställning", "text": [], "ovningar": [{"typ": "fri", "fraga": "Du har en blandning av fint grus, bordssalt och vatten. Beskriv i vilken ordning och med vilka metoder du kan få tillbaka (1) gruset, (2) saltet och (3) rent vatten. Förklara varför varje metod fungerar.", "forslag": "(1) Filtrera: gruset fastnar i filtret (residu) och saltvattnet rinner igenom (filtrat), så gruset är fast och olösligt. (2) Indunsta filtratet: vattnet förångas och saltet blir kvar, eftersom salt har mycket högre kokpunkt. (3) Vill du också ha rent vatten destillerar du filtratet: vattnet kokar först, kyls och kondenserar i kylaren och samlas upp, medan saltet blir kvar i kolven. Destillation ger alltså både vatten och salt, medan indunstning ger saltet men låter vattnet försvinna ut i luften."}, {"typ": "fri", "fraga": "Förklara varför en gas kan tryckas ihop men en vätska knappt kan det. Använd partikelmodellen. Förklara också en begränsning hos modellen, det vill säga något den inte visar.", "forslag": "I en gas är det stort tomrum mellan partiklarna, så de kan komma närmare varandra när man trycker. I en vätska ligger partiklarna redan nära varandra och det finns nästan inget tomrum. Begränsning: modellen är en 2D-bild som visar partiklar som kulor och inte rörelsen, krafterna eller energin."}]}, {"ikon": "📖", "titel": "Del E · Planera och resonera", "text": [], "ovningar": [{"typ": "fri", "fraga": "Du ska ta reda på om ett okänt vitt, fast ämne är salt, socker eller något annat. Planera en undersökning. Beskriv vilka egenskaper du mäter eller testar, vad du jämför med och hur du drar en slutsats. Förklara varför du behöver mer än en egenskap.", "forslag": "Öppet svar. Ett välutvecklat svar: mät densitet (massa/volym), smältpunkt, löslighet i vatten och ev. kokpunkt eller test med indikator, och jämför med tabellvärden (salt: smälter vid 802 °C, löser sig ca 36 g/100 ml; socker: löser sig mycket bättre). Smaka inte. Ett värde räcker inte eftersom flera ämnen kan ha liknande värde på en egenskap. Slutsatsen blir säkrare ju fler egenskaper som stämmer. Diskutera felkällor, att provet kan vara förorenat och att man bör upprepa."}, {"typ": "fri", "fraga": "Förklara hur man kan avgöra om ett prov är ett rent ämne eller en blandning med hjälp av smältpunkt eller kokpunkt. Diskutera också vad en sådan mätning kan och inte kan säga, och varför flera mätningar behövs.", "forslag": "Öppet svar. Ett rent ämne har en bestämd smältpunkt och kokpunkt, och temperaturen ligger still under smältningen. En blandning smälter eller kokar över ett temperaturområde och har ett annat värde än de rena ämnena. Mätningen kan visa att provet inte är rent men inte vilka ämnen det innehåller eller hur mycket. Flera mätningar behövs för att utesluta mätfel och bekräfta mönstret."}]}]}, "fordjupning": {"sektioner": [{"ikon": "💭", "titel": "Resonera och ta ställning", "text": ["Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led."], "ovningar": [{"typ": "fri", "fraga": "En djup insjö i norra Sverige är kall på vintern. En del tror att vattnet fryser till botten på vintern. a) Förklara med vattnets densitet varför bottenvattnet i en djup sjö kan vara kvar som flytande vatten. b) Vad händer med isen och vattnet längre ned? c) Vad skulle hända om is hade högre densitet än vatten?", "forslag": "a) Vatten är tätast vid 4 °C. Ytvattnet som kyls blir mindre tätt under 4 °C och ligger kvar överst, där det fryser. Det tyngre vattnet vid ca 4 °C ligger kvar nedanför. b) Isen flyter på ytan och isolerar. Vattnet under är ungefär 4 °C och fryser inte. c) Is skulle sjunka och frysa upp sjön underifrån. Sjön kunde frysa helt och djurlivet skulle ha svårt att klara vintern."}, {"typ": "fri", "fraga": "Elin värmer en isbit och mäter temperaturen varje minut. Hon ser att temperaturen ligger still vid 0 °C en stund och sedan stiger. a) Förklara varför temperaturen ligger still, med partikelmodellen. b) Förklara varför platån vid kokning blir längre än vid smältning om värmen tillförs jämnt. c) Hur skulle kurvan se ut om provet var saltvatten i stället för rent vatten?", "forslag": "a) Värmen går åt att bryta loss partiklarna från mönstret, inte att få dem att röra sig snabbare. Temperaturen, som mäter rörelsen, ändras då inte. b) Vid förångning ska partiklarna skiljas från varandra helt, vilket kräver mer energi än att bryta mönstret vid smältning. Därför tar det längre tid. c) Saltvatten är en blandning, så det smälter och kokar över ett temperaturområde och har inte en skarp platå. Kokpunkten blir också något högre än 100 °C."}, {"typ": "fri", "fraga": "Du löser 50 g salt i 100 ml vatten vid 20 °C. Saltets löslighet är ungefär 35,7 g per 100 ml vid 20 °C. a) Räkna ut hur mycket som löser sig och hur mycket som blir kvar. b) Är lösningen mättad? Motivera. c) En kamrat säger att allt kommer att lösa sig om man rör om länge. Värdera påståendet.", "forslag": "a) 35,7 g löser sig, 50 − 35,7 = 14,3 g blir kvar. b) Ja, mättad: det går inte att lösa mer vid 20 °C och överskottet ligger kvar. c) Påståendet stämmer inte: omrörning gör att det löser sig fortare, men inte mer. Löslighetsgränsen ändras bara med temperaturen eller lösningsmedlet."}, {"typ": "fri", "fraga": "En grupp hade 5,0 g salt före separationen och fick 4,1 g efter. a) Räkna ut utbytet. b) Ge tre tänkbara orsaker till att utbytet är under 100 %. c) En annan grupp fick 5,4 g. Vad kan det betyda, och hur kan gruppen kontrollera det?", "forslag": "a) 4,1 / 5,0 × 100 = 82 %. b) T.ex. salt som fastnat på filter, bägare och skål, spill, och salt som sprutat vid upphettningen. c) Mer än 100 % är orimligt och tyder på fukt eller sand i saltet. Kontrollera genom att torka längre, väga om och göra om försöket."}, {"typ": "fri", "fraga": "Två vätskor, A och B, har kokpunkterna 78 °C och 82 °C. a) Förklara varför en enkel destillation inte ger rena vätskor. b) Beskriv hur fraktionerad destillation förbättrar separationen. c) Hur kan temperaturen på termometern användas för att avgöra när du ska byta uppsamlingskärl?", "forslag": "a) Ångan innehåller båda ämnena, med mer av det som kokar vid lägst temperatur. Kokpunkterna ligger nära varandra så ångan blir bara lite rikare. b) Kolonnen låter ångan kondensera och förångas många gånger. Varje gång blir ångan rikare på det lågkokande ämnet och till slut kommer nästan rent A ut. c) Vid ca 78 °C kommer ämnet med lägre kokpunkt, och när temperaturen stiger mot 82 °C byter man kärl för nästa fraktion."}, {"typ": "fri", "fraga": "Du ska ta reda på vad ett okänt, vitt pulver är. Kandidater: bordssalt, socker och bikarbonat. a) Planera en undersökning med minst tre oberoende metoder och förklara varför du behöver mer än en. b) Beskriv vilka kontrollprov du använder. c) Förklara vad du kan och inte kan säga om du bara hittar skillnader mot salt och socker.", "forslag": "a) T.ex. löslighet i vatten, smältpunkt, om det bildar fällning eller skummar med syra, och densitet. Man behöver flera eftersom flera ämnen kan ha liknande värde på en egenskap. b) Prov av känt salt, socker och bikarbonat som testas på samma sätt, och ev. blankprov med bara vatten. c) Att provet inte är de testade ämnena, men inte vad det är. Det kan vara ett ämne du inte testat."}]}]}}, nivaStandard: "vanlig"};
